import{loadHubResources}from'./hub-resources.mjs';
const assetModuleURL=import.meta.url;
const manifests=Object.freeze({legacy:['./HUB_RESOURCE_PINS.json','4b7a4316a626b4c44748d351cea96b2fbfe009da59dfa2ec4f3cf2122b756d94'],current:['./EXTRA_RESOURCE_PINS.json','426a2098e644d322da7f2703e8a47a89f88a5bc39866182358e48123f1f1944c']});
const digest=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadLazyHubResources({signal}={}){
 let disposed=false,presentation=null,pending=null,epoch=0,cleanupFailureCount=0,lastCleanupFailure=null;const masks={legacy:{},current:{}};
 const check=()=>{if(disposed||signal?.aborted)throw Error('HUB_LAZY_CANCELLED')};
 async function read(url,sha){check();const r=await fetch(url,{signal});if(!r.ok)throw Error('HUB_SUPPORT_MISSING');const b=await r.arrayBuffer();check();if(await digest(b)!==sha)throw Error('HUB_SUPPORT_PIN');check();return b}
 async function floor(bytes){let image,canvas,primary;try{image=await createImageBitmap(new Blob([bytes]));check();if(image.width!==3656||image.height!==1792)throw Error('HUB_SUPPORT_DIMENSIONS');canvas=document.createElement('canvas');canvas.width=3656;canvas.height=1792;const g=canvas.getContext('2d');g.drawImage(image,0,0);const rgba=g.getImageData(0,0,3656,1792).data;check();return Uint8Array.from({length:3656*1792},(_,i)=>rgba[i*4]>127?1:0)}catch(e){primary=e;throw e}finally{let cleanup;try{if(canvas){canvas.width=1;canvas.height=1}}catch(e){cleanup=e}try{image?.close?.()}catch(e){cleanup??=e}if(!primary&&cleanup)throw cleanup}}
 for(const[k,[url,sha]]of Object.entries(manifests)){const pins=JSON.parse(new TextDecoder().decode(await read(new URL(url,assetModuleURL),sha)));for(const state of['OPEN','CLOSED']){const pin=pins['floor_'+state.toLowerCase()+'.png'];if(!pin?.url||!/^[0-9a-f]{64}$/.test(pin.sha256))throw Error('HUB_SUPPORT_KEY');masks[k][state]=await floor(await read(new URL(pin.url,assetModuleURL),pin.sha256))}}check();
 function safeFor(kind,[x,y],state){const m=masks[kind][state];if(disposed||!m||!Number.isInteger(x)||!Number.isInteger(y)||x<24||y<18||x+24>=3656||y+18>=1792)return false;for(let yy=y-18;yy<=y+18;yy++)for(let xx=x-24;xx<=x+24;xx++)if(!m[yy*3656+xx]||kind==='current'&&xx>=3164&&xx<3213&&yy>=518&&yy<555)return false;return true}
 function noteCleanup(e){cleanupFailureCount++;lastCleanupFailure=String(e?.message??e).slice(0,240)}
 function releasePresentation(){const old=presentation;presentation=null;epoch++;try{old?.dispose()}catch(e){noteCleanup(e)}}
 async function ensurePresentation(){check();if(presentation)return;if(pending)return pending;const mine=epoch;pending=(async()=>{let next;try{next=await loadHubResources();check();if(mine!==epoch)throw Error('HUB_LAZY_STALE');presentation=next;next=null}finally{if(next){try{next.dispose()}catch(e){noteCleanup(e)}}}})();try{return await pending}finally{pending=null}}
 return{get cleanupDiagnostics(){return Object.freeze({failureCount:cleanupFailureCount,lastFailure:lastCleanupFailure})},get pinsVerified(){return!disposed},get presentationReady(){return!disposed&&!!presentation},safe:(f,s)=>safeFor('current',f,s),legacySafe:(f,s)=>safeFor('legacy',f,s),get items(){if(!presentation||disposed)throw Error('HUB_PRESENTATION_NOT_PREPARED');return presentation.items},render(o){if(!presentation||disposed)throw Error('HUB_PRESENTATION_NOT_PREPARED');return presentation.render(o)},ensurePresentation,releasePresentation,dispose(){if(disposed)return;disposed=true;try{releasePresentation()}finally{for(const group of Object.values(masks))for(const k of Object.keys(group))delete group[k]}}};
}
